float shadowRand(float2 p)
{
    return frac(sin(dot(p, float2(12.9898, 78.233))) * 43758.5453);
}

float CalcShadow(float3 worldPos, float3 normal, float3 lightDir, float farDist)
{
    float NdotL = dot(normal, lightDir);
    if (NdotL <= 0.0) return 1.0;

    float4 lightSpace = mul(float4(worldPos, 1.0), g_lightViewProj);
    lightSpace.xyz /= lightSpace.w;
    float2 uv = lightSpace.xy * float2(0.5, -0.5) + 0.5;
    float currentDepth = lightSpace.z;

    float2 edge = min(uv, 1.0 - uv);
    float fadeUV = smoothstep(0.0, 0.05, min(edge.x, edge.y));
    float fadeZ  = 1.0 - smoothstep(0.95, 1.0, currentDepth);
    float fade   = fadeUV * fadeZ;
    if (fade <= 0.0 || currentDepth < 0.0) return 1.0;

    float bias = max(0.002 * (1.0 - NdotL), 0.0005);

    float lightSize = 4.0;
    float texelSize = 1.0 / 2048.0;

    float ang = shadowRand(uv) * 6.2831853;
    float cs = cos(ang), sn = sin(ang);
    float2x2 rot = float2x2(cs, -sn, sn, cs);

    float3 toCam = g_camPos - worldPos;
    [branch] if (dot(toCam, toCam) > farDist * farDist)
    {
        float r4 = 2.0 * texelSize;
        float s4 = 0.0;
        [unroll] for (int k = 0; k < 4; ++k)
        {
            float2 o = mul(kPoisson[k * 4], rot) * r4;
            float sd = g_shadowMap.SampleLevel(g_sampler, saturate(uv + o), 0).r;
            s4 += (currentDepth - bias > sd) ? 0.0 : 1.0;
        }
        return lerp(1.0, s4 * 0.25, fade);
    }

    float searchRadius = lightSize * texelSize;
    float blockerSum = 0.0;
    float blockerCount = 0.0;
    [unroll] for (int i = 0; i < 16; ++i)
    {
        float2 o = mul(kPoisson[i], rot) * searchRadius;
        float sd = g_shadowMap.SampleLevel(g_sampler, saturate(uv + o), 0).r;
        if (sd < currentDepth - bias)
        {
            blockerSum += sd;
            blockerCount += 1.0;
        }
    }
    if (blockerCount < 0.5) return 1.0;
    float avgBlocker = blockerSum / blockerCount;

    float penumbra = (currentDepth - avgBlocker) / max(avgBlocker, 0.0001);
    float filterRadius = penumbra * lightSize * texelSize;
    filterRadius = clamp(filterRadius, texelSize, 8.0 * texelSize);

    float shadow = 0.0;
    [unroll] for (int j = 0; j < 16; ++j)
    {
        float2 o = mul(kPoisson[j], rot) * filterRadius;
        float sd = g_shadowMap.SampleLevel(g_sampler, saturate(uv + o), 0).r;
        shadow += (currentDepth - bias > sd) ? 0.0 : 1.0;
    }
    shadow /= 16.0;

    return lerp(1.0, shadow, fade);
}
float3 CalcShadowDebug(float3 worldPos)
{
    float4 lightSpace = mul(float4(worldPos, 1.0), g_lightViewProj);
    lightSpace.xyz /= lightSpace.w;
    float2 uv = lightSpace.xy * float2(0.5, -0.5) + 0.5;
    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) return float3(0,0,1);
    float shadowDepth = g_shadowMap.Sample(g_sampler, uv).r;
    float currentDepth = lightSpace.z;
    float bias = 0.1;
    float s = (currentDepth - bias > shadowDepth) ? 0.0 : 1.0;
    return float3(s, s, s);
}

float3 colorGradeAdvanced(float3 col)
{
    float3 lift  = float3(0.0, 0.0, 0.02);   
    float3 gamma = float3(1.0, 1.0, 1.0);   
    float3 gain  = float3(1.05, 1.0, 0.95);  

    col = col * (1.0 - lift) + lift;
    col = col * gain;
    col = pow(max(col, 0.0), 1.0 / gamma);

    float contrast = 1.1;
    col = (col - 0.5) * contrast + 0.5;

    float saturation = 1.1;
    float lum = dot(col, float3(0.299, 0.587, 0.114));
    col = lerp(float3(lum, lum, lum), col, saturation);

    float luma = dot(col, float3(0.299, 0.587, 0.114));
    float3 shadowTint = float3(0.95, 0.98, 1.05);  
    float3 highTint   = float3(1.05, 1.0, 0.95);
    float3 tint = lerp(shadowTint, highTint, smoothstep(0.0, 1.0, luma));
    col *= tint;

    return saturate(col);
}
