float D_GGX(float NdotH, float roughness)
{
    float a = roughness * roughness;
    float a2 = a * a;
    float d = NdotH * NdotH * (a2 - 1.0) + 1.0;
    return a2 / (3.14159265 * d * d);
}
float G_SchlickGGX(float NdotV, float roughness)
{
    float r = roughness + 1.0;
    float k = (r * r) / 8.0;
    return NdotV / (NdotV * (1.0 - k) + k);
}
float G_Smith(float NdotV, float NdotL, float roughness)
{
    return G_SchlickGGX(NdotV, roughness) * G_SchlickGGX(NdotL, roughness);
}
float3 F_Schlick(float HdotV, float3 F0)
{
    return F0 + (1.0 - F0) * pow(1.0 - HdotV, 5.0);
}
float3 PBRLighting(float3 n, float3 v, float3 l, float3 lightColor,
                   float3 albedo, float metallic, float roughness)
{
    float3 h = normalize(v + l);
    float NdotV = max(dot(n, v), 0.0001);
    float NdotL = max(dot(n, l), 0.0001);
    float NdotH = max(dot(n, h), 0.0);
    float HdotV = max(dot(h, v), 0.0);
    float3 F0 = lerp(float3(0.04, 0.04, 0.04), albedo, metallic);
    float  D = D_GGX(NdotH, roughness);
    float  G = G_Smith(NdotV, NdotL, roughness);
    float3 F = F_Schlick(HdotV, F0);
    float3 specular = (D * G * F) / (4.0 * NdotV * NdotL);
    float3 kd = (1.0 - F) * (1.0 - metallic);
    float3 diffuse = kd * albedo / 3.14159265;
    return (diffuse + specular) * lightColor * NdotL;
}
float DistanceAttenuation(float distSq, float range)
{
    float atten = 1.0 / max(distSq, 0.0001);
    float f = distSq / max(range * range, 0.0001);
    float w = saturate(1.0 - f * f);
    return atten * w * w;
}
float3 PBRLightingSphere(float3 n, float3 v, float3 Lvec, float3 lightColor,
                         float3 albedo, float metallic, float roughness,
                         float sphereRadius, float atten)
{
    float  dist = max(length(Lvec), 0.0001);
    float3 Lc   = Lvec / dist;
    float3 F0   = lerp(float3(0.04, 0.04, 0.04), albedo, metallic);
    float  NdotV = max(dot(n, v), 0.0001);

    float  NdotLc = max(dot(n, Lc), 0.0);
    float3 hc = normalize(v + Lc);
    float3 Fd = F_Schlick(max(dot(hc, v), 0.0), F0);
    float3 kd = (1.0 - Fd) * (1.0 - metallic);
    float3 diffuse = kd * albedo / 3.14159265 * NdotLc;

    float3 r = reflect(-v, n);
    float3 centerToRay = dot(Lvec, r) * r - Lvec;
    float3 closest = Lvec + centerToRay * saturate(sphereRadius / max(length(centerToRay), 0.0001));
    float3 Ls = normalize(closest);
    float  NdotLs = max(dot(n, Ls), 0.0001);
    float3 hs = normalize(v + Ls);
    float  NdotH = max(dot(n, hs), 0.0);
    float  HdotV = max(dot(hs, v), 0.0);

    float  a  = max(roughness * roughness, 0.001);
    float  aP = saturate(a + sphereRadius / (2.0 * dist));
    float  norm = (a / aP) * (a / aP);

    float  D = D_GGX(NdotH, roughness);
    float  G = G_Smith(NdotV, NdotLs, roughness);
    float3 F = F_Schlick(HdotV, F0);
    float3 specular = (D * G * F) / (4.0 * NdotV * NdotLs) * norm * NdotLs;
    specular = min(specular, 16.0);

    return (diffuse + specular) * lightColor * atten;
}


